import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, mul, sub } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container (position/rotation/scale will be applied by the adapter)
  const root = new Group();

  // --------------------------------------------------------------------
  // 1. TEXTURED PLANE (sprite)
  // --------------------------------------------------------------------
  // Use the atlas source rect to compute aspect ratio.
  // If the spec does not expose the rect directly, fall back to a default.
  const rect = (config.atlasRegion && config.atlasRegion.sourceRect) || {
    width: 512,
    height: 320,
  };
  const aspect = rect.width / rect.height;

  const geometry = new PlaneGeometry(aspect, 1, 1, 1);

  const material = new MeshBasicNodeMaterial();

  // Load texture (static image)
  // The loader returns a cached Promise; we attach the texture when ready.
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    // Attach texture as a node – the material will automatically wrap plain textures.
    material.map = tex;
    material.needsUpdate = true;
  });

  const sprite = new Mesh(geometry, material);
  sprite.frustumCulled = false; // ensure visibility even if tiny

  // Billboard: always face the camera.
  sprite.onBeforeRender = function (_, __, camera) {
    sprite.quaternion.copy(camera.quaternion);
  };

  root.add(sprite);

  // --------------------------------------------------------------------
  // 2. TEXT LABEL
  // --------------------------------------------------------------------
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  for (const item of items) {
    // Font size from spec – fallback to the numeric value used in the description.
    const fontSize = item.typography?.fontSize ?? 39;

    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color: config.visualSpec?.colors?.paper ?? '#e8ecf2',
      align: 'center',
    });

    // Position the text slightly in front of the plane so it does not Z‑fight.
    txt.position.set(0, 0, 0.01);
    root.add(txt);
  }

  // --------------------------------------------------------------------
  // 3. USERDATA & CLEANUP
  // --------------------------------------------------------------------
  root.userData.handlers = {}; // no interactive handlers defined

  // Store references that need disposal.
  const disposables = [{ geometry, material }];

  root.userData.cleanup = () => {
    // Dispose geometries and materials.
    for (const d of disposables) {
      d.geometry && d.geometry.dispose && d.geometry.dispose();
      d.material && d.material.dispose && d.material.dispose();
    }

    // Kill any GSAP timelines that might have been created (none in this node).
    gsap.globalTimeline.clear();
  };

  return root;
}
